import React, { useState } from 'react';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_COLOR = { 1:'#8B3A3A', 2:'#8B5A3A', 3:'#6B6B3A', 4:'#2D6B6B', 5:'#3A6B8B' };

const ACTIVITY_LABELS = {
  workout:'🏃 Workout', social:'👥 Socialised', work:'💼 Work',
  nature:'🌿 Nature', creative:'🎨 Creative', screen:'📱 Lots of screen',
  alcohol:'🍷 Alcohol', meditation:'🧘 Meditation', reading:'📖 Read',
  alone:'🌙 Alone time', conflict:'⚡ Conflict', goodsleep:'😴 Slept well',
  badsleep:'🥴 Slept badly', goodfood:'🥗 Ate well',
};

const css = {
  page:  { background: '#EEEAE3', minHeight: '100vh', overflowY: 'auto' },
  inner: { padding: '56px 28px 110px' },
  h:     { fontSize: 38, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#1A2A2A', marginBottom: 24 },
  lbl:   { fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: 12 },
};

function MiniBar({ value, max = 5, color = '#2D6B6B' }) {
  return (
    <div style={{ height: 4, background: 'rgba(26,42,42,0.08)', borderRadius: 2, overflow: 'hidden', flex: 1 }}>
      <div style={{ height: '100%', width: `${(value / max) * 100}%`, background: color, borderRadius: 2 }} />
    </div>
  );
}

export default function History({ setPage }) {
  const { moods, streak, activityCorrelations } = useMoods();
  const { thoughts, trapCounts }                = useThoughts();
  const [expanded, setExpanded]                 = useState(null);

  const isEmpty = moods.length === 0 && thoughts.length === 0;

  if (isEmpty) return (
    <div style={{ ...css.page, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{ padding: '0 28px', textAlign: 'center' }}>
        <p style={{ fontSize: 18, color: 'rgba(26,42,42,0.4)', lineHeight: 1.6, marginBottom: 32 }}>
          Nothing here yet.<br />Start with a check-in.
        </p>
        <button onClick={() => setPage('checkin')} style={{ padding: '16px 28px', borderRadius: 20, background: '#1A2A2A', color: '#EEEAE3', fontSize: 15, fontWeight: 600 }}>
          Check-in →
        </button>
      </div>
    </div>
  );

  // Average sliders from last 7 entries that have slider data
  const sliderEntries = moods.filter(m => m.energy != null).slice(0, 7);
  const avg = (key) => sliderEntries.length
    ? Math.round((sliderEntries.reduce((a, m) => a + m[key], 0) / sliderEntries.length) * 10) / 10
    : null;

  const avgEnergy  = avg('energy');
  const avgAnxiety = avg('anxiety');
  const avgSleep   = avg('sleep');
  const avgFocus   = avg('focus');

  // Top activity correlations
  const topCorr = Object.entries(activityCorrelations)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 4);

  return (
    <div style={css.page}>
      <div style={css.inner}>
        <h2 style={css.h}>History.</h2>

        {/* Stats */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 28 }}>
          <div style={{ padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)' }}>
            <div style={{ fontSize: 46, fontWeight: 700, letterSpacing: '-0.05em', color: '#1A2A2A', lineHeight: 1 }}>{thoughts.length}</div>
            <div style={{ fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 4 }}>Analyses</div>
          </div>
          <div style={{ padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)' }}>
            <div style={{ fontSize: 46, fontWeight: 700, letterSpacing: '-0.05em', color: '#2D6B6B', lineHeight: 1 }}>{streak}</div>
            <div style={{ fontSize: 11, fontWeight: 600, color: 'rgba(26,42,42,0.3)', textTransform: 'uppercase', letterSpacing: '0.08em', marginTop: 4 }}>Day streak</div>
          </div>
        </div>

        {/* Mood bars */}
        {moods.length > 0 && (
          <>
            <div style={css.lbl}>Mood</div>
            <div style={{ display: 'flex', alignItems: 'flex-end', gap: 5, height: 48, marginBottom: 28 }}>
              {moods.slice(0, 14).reverse().map((m, i) => (
                <div key={i} style={{ flex: 1, borderRadius: 4, background: MOOD_COLOR[m.score] || '#2D6B6B', height: 10 + (m.score / 5) * 38, opacity: 0.3 + (m.score / 5) * 0.7 }} />
              ))}
            </div>
          </>
        )}

        {/* Slider averages */}
        {avgEnergy !== null && (
          <>
            <div style={css.lbl}>Last 7 days — average</div>
            <div style={{ padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)', marginBottom: 28 }}>
              {[
                { label: 'Energy',  val: avgEnergy,  color: '#2D6B6B' },
                { label: 'Anxiety',  val: avgAnxiety, color: '#8B5A3A' },
                { label: 'Sleep',    val: avgSleep,   color: '#3A6B8B' },
                { label: 'Focus',   val: avgFocus,   color: '#6B3A8B' },
              ].map(({ label, val, color }) => (
                <div key={label} style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
                  <span style={{ fontSize: 13, fontWeight: 500, color: 'rgba(26,42,42,0.5)', width: 60, flexShrink: 0 }}>{label}</span>
                  <MiniBar value={val} color={color} />
                  <span style={{ fontSize: 13, fontWeight: 700, color: '#1A2A2A', width: 28, textAlign: 'right', flexShrink: 0 }}>{val}</span>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Activity correlations */}
        {topCorr.length > 0 && (
          <>
            <div style={css.lbl}>Activities → mood</div>
            <div style={{ padding: 20, borderRadius: 22, background: 'rgba(255,255,255,0.55)', border: '1px solid rgba(255,255,255,0.85)', marginBottom: 28 }}>
              {topCorr.map(([act, avgScore]) => (
                <div key={act} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '9px 0', borderBottom: '1px solid rgba(26,42,42,0.06)' }}>
                  <span style={{ fontSize: 14, fontWeight: 500, color: '#1A2A2A' }}>{ACTIVITY_LABELS[act] || act}</span>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <div style={{ width: 48, height: 4, background: 'rgba(26,42,42,0.08)', borderRadius: 2, overflow: 'hidden' }}>
                      <div style={{ height: '100%', width: `${(avgScore / 5) * 100}%`, background: '#2D6B6B', borderRadius: 2 }} />
                    </div>
                    <span style={{ fontSize: 13, fontWeight: 700, color: '#2D6B6B', width: 28 }}>{avgScore}</span>
                  </div>
                </div>
              ))}
              <p style={{ fontSize: 11, color: 'rgba(26,42,42,0.3)', marginTop: 12, lineHeight: 1.5 }}>Average mood on days with each activity</p>
            </div>
          </>
        )}

        {/* Trap counts */}
        {Object.keys(trapCounts).length > 0 && (
          <>
            <div style={css.lbl}>Thought traps</div>
            <div style={{ marginBottom: 28 }}>
              {Object.entries(trapCounts).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([label, count]) => (
                <div key={label} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '13px 0', borderBottom: '1px solid rgba(26,42,42,0.06)' }}>
                  <span style={{ fontSize: 15, fontWeight: 500, color: '#1A2A2A', letterSpacing: '-0.02em' }}>{label}</span>
                  <span style={{ padding: '4px 12px', borderRadius: 999, background: 'rgba(45,107,107,0.1)', fontSize: 12, fontWeight: 600, color: '#2D6B6B' }}>{count}×</span>
                </div>
              ))}
            </div>
          </>
        )}

        {/* Thought log */}
        {thoughts.length > 0 && (
          <>
            <div style={css.lbl}>Log</div>
            {thoughts.map((th, i) => (
              <div key={th.id} onClick={() => setExpanded(expanded === i ? null : i)}
                style={{ padding: 18, borderRadius: 20, marginBottom: 8, background: expanded === i ? 'rgba(255,255,255,0.75)' : 'rgba(255,255,255,0.5)', border: '1px solid rgba(255,255,255,0.8)', cursor: 'pointer', transition: 'background 0.15s' }}>
                <div style={{ fontSize: 10, fontWeight: 700, color: '#2D6B6B', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 6 }}>{th.trap_label}</div>
                <div style={{ fontSize: 14, color: 'rgba(26,42,42,0.5)', fontStyle: 'italic', lineHeight: 1.55 }}>
                  "{th.user_text?.slice(0, 70)}{th.user_text?.length > 70 ? '…' : ''}"
                </div>
                {expanded === i && (
                  <div style={{ fontSize: 14, color: '#1A2A2A', lineHeight: 1.65, marginTop: 12, paddingTop: 12, borderTop: '1px solid rgba(26,42,42,0.07)', animation: 'fadeIn 0.2s both' }}>
                    {th.reframe}
                  </div>
                )}
              </div>
            ))}
          </>
        )}

        {/* Daily entries */}
        {moods.some(m => m.note || m.activities?.length > 0) && (
          <>
            <div style={{ ...css.lbl, marginTop: 8 }}>Journal entries</div>
            {moods.filter(m => m.note || m.activities?.length > 0).slice(0, 5).map((m, i) => (
              <div key={m.id} style={{ padding: 18, borderRadius: 20, marginBottom: 8, background: 'rgba(255,255,255,0.5)', border: '1px solid rgba(255,255,255,0.8)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                  <span style={{ fontSize: 18 }}>{m.emoji}</span>
                  <span style={{ fontSize: 11, color: 'rgba(26,42,42,0.3)', fontFamily: 'monospace' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE', { day: '2-digit', month: '2-digit' })}
                  </span>
                </div>
                {m.activities?.length > 0 && (
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: m.note ? 8 : 0 }}>
                    {m.activities.map(act => (
                      <span key={act} style={{ fontSize: 12, padding: '3px 10px', borderRadius: 999, background: 'rgba(45,107,107,0.08)', color: '#2D6B6B', fontWeight: 500 }}>
                        {ACTIVITY_LABELS[act] || act}
                      </span>
                    ))}
                  </div>
                )}
                {m.note && <p style={{ fontSize: 13, color: 'rgba(26,42,42,0.5)', fontStyle: 'italic', lineHeight: 1.6 }}>"{m.note}"</p>}
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
